use super::*;
#[test]fn checked_outside_memory_retains_prefix_and_cross_kind_alias(){let mut s=State::default();let end=BASE+BLOCK as u32;assert!(s.write(end-2,&[1,2,3,4]).is_ok());assert_eq!(s.read(end,2).unwrap(),&[3,4]);let end=BASE+(BLOCK*4)as u32;assert!(s.write(end-2,&[5,6,7,8]).is_err());assert_eq!(s.read(end-2,2).unwrap(),&[5,6]);}
#[test]fn full_jobs_do_not_touch_recycled_payload_and_mission_reset_preserves_arena(){let mut s=State::default();for j in &mut s.jobs{j.0.fill(137);}let jobs=s.jobs;assert_eq!(s.free_job(),None);assert_eq!(s.birth(1,[2,3],BASE,4).unwrap(),None);assert_eq!(s.jobs,jobs);s.arena[17]=99;s.mission_reset();assert_eq!(s.arena[17],99);assert!(s.jobs.iter().all(|j|j.0==[0;24]));}

pub(crate)fn fixture(name:&str)->Vec<serde_json::Value>{
 if let Some(root)=std::env::var_os("Z_NATIVE_TRACE_DIR"){return std::fs::read_to_string(std::path::PathBuf::from(root).join(name)).expect("explicit private original fixture").lines().map(|s|serde_json::from_str(s).unwrap()).collect();}
 //Only generated inputs and numeric hashes. No original record/frame bytes.
 let all:serde_json::Value=serde_json::from_str(include_str!("original_building_trail_goldens.json")).unwrap();let d=&all[name];let keys=d["columns"].as_array().unwrap();d["rows"].as_array().unwrap().iter().map(|r|serde_json::Value::Object(keys.iter().zip(r.as_array().unwrap()).map(|(k,v)|(k.as_str().unwrap().to_string(),v.clone())).collect())).collect()
}
pub(crate)fn check_record(r:&serde_json::Value,key:&str,actual:&[u8]){if let Some(h)=r[key].as_str(){assert_eq!(actual,bytes(h),"private field comparison {key}");}else{assert_eq!(hash(actual.iter().copied()),r[format!("{key}Hash")].as_u64().unwrap()as u32,"native numeric record hash {key}");}}
fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn hash(v:impl IntoIterator<Item=u8>)->u32{v.into_iter().fold(2166136261u32,|h,b|(h^u32::from(b)).wrapping_mul(16777619))}
#[test]fn sixty_four_actual_loader_pools_match_every_runtime_byte(){let rows=fixture("v43-building-loader.jsonl");assert_eq!(rows.len(),64);for r in rows{let s=r["scenario"].as_u64().unwrap()as usize;let mut state=State::default();for(i,b)in state.builds.iter_mut().flatten().enumerate(){*b=(s*17+i*13+19)as u8;}let disk=(0..r["count"].as_u64().unwrap()as usize).map(|slot|std::array::from_fn(|i|(s*23+(slot*80+i)*29+31)as u8)).collect::<Vec<[u8;80]>>();state.load_buildings(&disk);check_record(&r,"pool",&state.builds.into_iter().flatten().collect::<Vec<_>>());}}
#[test]fn all_256_actual_job_birth_records_preserve_unwritten_bytes(){let rows=fixture("v43-trail-job-birth.jsonl");assert_eq!(rows.len(),256);for r in rows{let n=|k:&str|r[k].as_u64().unwrap()as usize;let s=n("scenario");let mut state=State::default();for(slot,j)in state.jobs.iter_mut().enumerate(){for(i,b)in j.0.iter_mut().enumerate(){*b=(s*31+slot*19+i*23+37)as u8;}j.set_ptr(0,if slot==n("free"){0}else{BASE});}let frame=[0,1,44,127,128,255][s%6];state.write(BASE+11,&[frame]).unwrap();if n("busy")==0{state.birth(0x1800100,[(400+s*3)as i16,(500+s*5)as i16],BASE,0x1800000).unwrap();}assert_eq!(hash(state.jobs.iter().flat_map(|j|j.0)),n("jobs")as u32);if n("free")<64{check_record(&r,"created",&state.jobs[n("free")].0);}}}

use super::super::effects::{self,spray::Pool,bridge};
struct PoolWorld{pool:Vec<[u8;44]>,limit:usize,rng:crate::original_combat::OriginalRng,calls:usize,requests:usize}
impl Pool for PoolWorld{fn first_free(&self)->Option<usize>{self.pool.iter().take(self.limit).position(|b|i16::from_le_bytes([b[0],b[1]])==-1000)}fn load(&mut self,n:usize)->[u8;44]{self.pool[n]}fn store(&mut self,n:usize,b:[u8;44]){self.pool[n]=b;}fn random(&mut self)->u32{self.calls+=1;self.rng.next_u32()}}
impl bridge::World for PoolWorld{fn retire(&mut self,n:usize){self.pool[n][..2].copy_from_slice(&(-1000i16).to_le_bytes());}fn before_emit(&mut self,_:u16,_:&bridge::Globals){self.requests+=1;}}
fn seed(s:usize,k:usize,mp:bool)->crate::original_combat::OriginalRng{crate::original_combat::OriginalRng{words:std::array::from_fn(|i|0x173510a7u32.wrapping_add(s as u32*7919+k as u32*31).wrapping_add((i as u32).wrapping_mul(0x9e3779b9))),multiplayer:mp}}
fn check_rng(r:&serde_json::Value,w:&PoolWorld){for i in 0..5{assert_eq!(w.rng.words[i],r[format!("r{i}")].as_u64().unwrap()as u32);}}
fn step_part(t:&mut State,w:&mut PoolWorld,g:&mut bridge::Globals,at:usize,projection:&mut[i16;2],camera:[i16;2],sound:&mut bool)->(usize,Vec<u32>){let mut p=Particle::from_bytes(w.pool[at]);if !p.active{return(0,vec![]);}let view=effects::View{camera,clip:[0,0,1024,1024],world:[4096,4096],sine:crate::native_math::sine(425),cosine:crate::native_math::sine(553)};let step=p.advance_native_trail(view,projection,t);let mut calls=vec![];if let Some(d)=step.draw{if d.sprite>=250&&p.sprite==250{calls.push(0x4666c0);}else{calls.extend([0x40bb50,0x466ac0]);}}w.pool[at]=p.bytes();if step.expiry==Some(3){let point=[p.origin[0].wrapping_add(projection[0]),p.origin[1].wrapping_add(projection[1])];let screen=[point[0].wrapping_sub(camera[0]),point[1].wrapping_sub(camera[1])];if screen[0]>=-48&&screen[0]<=1056&&screen[1]>=-48&&screen[1]<=1056{*sound=true;}if point[0]>=-32{calls.push(0x420200);}calls.push(0x41f2d0);expiry_children(w,g,at,point);(1,calls)}else{(0,calls)}}
#[test]fn two_original_same_kind_destructions_match_all_3584_pool_and_trail_states(){let rows=fixture("v43-double-destruction.jsonl");assert_eq!(rows.len(),3584);let mut last=(usize::MAX,usize::MAX);let mut t=State::default();let mut w=PoolWorld{pool:vec![],limit:0,rng:seed(0,0,false),calls:0,requests:0};let mut g=bridge::Globals::default();let mut projection=[160,100];let mut sound=false;for r in rows{let n=|k:&str|r[k].as_i64().unwrap();let(k,s,op)=(n("kind")as usize,n("scenario")as usize,n("op"));if(k,s)!=last{last=(k,s);t=State::default();for(i,b)in t.arena.iter_mut().enumerate(){*b=(s*11+k*31+i*7+19)as u8;}t.error=9;w=PoolWorld{pool:(0..500usize).map(|slot|{let mut b=std::array::from_fn(|j|(s*17+k*31+slot*13+j*19)as u8);b[..2].copy_from_slice(&(if s>=32&&slot>=n("n")as usize{0i16}else{-1000}).to_le_bytes());b}).collect(),limit:n("capacity")as usize,rng:seed(s,k,n("mp")!=0),calls:0,requests:0};g=bridge::Globals{maximum:99,suppression:n("gate")as u8,context:effects::spray::Context{tint:37,..Default::default()},raw:bridge::Raw{byte32:69,payload36:0x12345678,payload40:0xabcdef01,last_record:Some(0xdeadbeef),..Default::default()}};projection=[160,100];sound=false;}
 assert_eq!(hash(t.arena.iter().copied()),n("beforeTrail")as u32);assert_eq!(hash(w.pool.iter().flatten().copied()),n("beforePool")as u32);w.calls=0;w.requests=0;let(mut dispatch,mut leaves)=(0,vec![]);if op==0||op==5{leaves.push(0x40cc90);prefix(&mut t,&mut w,&mut g,k as i8,if op==0{[400,500]}else{[900,700]}).unwrap();leaves.extend([0x40e6a0,0x459d10]);}else if n("actor")>=0{let at=n("actor")as usize;if i16::from_le_bytes(w.pool[at][..2].try_into().unwrap())!=-1000{if op>=12{w.pool[at][18..20].fill(0);w.pool[at][4..6].copy_from_slice(&(-1i16).to_le_bytes());}let d=step_part(&mut t,&mut w,&mut g,at,&mut projection,[0,0],&mut sound);dispatch=d.0;leaves=d.1;}}
 assert_eq!(hash(w.pool.iter().flatten().copied()),n("pool")as u32,"pool kind{k}/s{s}/op{op}");assert_eq!(hash(t.arena.iter().copied()),n("trail")as u32,"trail kind{k}/s{s}/op{op}");assert_eq!(leaves,r["leaves"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u32).collect::<Vec<_>>());assert_eq!((w.calls,w.requests,dispatch),(n("calls")as usize,n("requests")as usize,n("dispatch")as usize));assert_eq!(projection,[n("projectX")as i16,n("projectY")as i16]);assert_eq!(g.raw.byte32,n("byte32")as u8);assert_eq!(g.raw.payload36,n("payload36")as u32);assert_eq!(g.raw.payload40,n("payload40")as u32);assert_eq!(g.raw.last_record,Some(n("last")as u32));assert_eq!(g.maximum,n("maximum")as u8);assert_eq!(g.context.tint,n("tint")as u8);assert_eq!(g.suppression,n("suppression")as u8);assert_eq!(t.error,n("error")as u8);assert_eq!(sound,n("soundGate")!=0);check_rng(&r,&w);if n("actor")>=0{check_record(&r,"actorBytes",&w.pool[n("actor")as usize]);}}
}

#[test]fn all_1024_original_owner4_callbacks_match_records_trails_projection_and_rng(){let rows=fixture("v43-owner4-particle.jsonl");assert_eq!(rows.len(),1024);let mut prev=usize::MAX;let mut t=State::default();let mut w=PoolWorld{pool:vec![],limit:0,rng:seed(0,0,false),calls:0,requests:0};let mut g=bridge::Globals::default();let mut projection=[160,100];for r in rows{let n=|k:&str|r[k].as_i64().unwrap();let s=n("scenario")as usize;if s!=prev{prev=s;t=State::default();for(i,b)in t.arena.iter_mut().enumerate(){*b=(s*11+i*7+19)as u8;}t.error=9;w=PoolWorld{pool:(0..500usize).map(|slot|{let mut b=std::array::from_fn(|j|(s*17+slot*13+j*19)as u8);b[..2].copy_from_slice(&(if slot==0||s>>4&1==0{0i16}else{-1000}).to_le_bytes());b}).collect(),limit:n("capacity")as usize,rng:seed(s,0,n("mp")!=0),calls:0,requests:0};w.pool[0]=particle_source(s,&r);g=bridge::Globals{maximum:11,suppression:(s/64%2)as u8,context:effects::spray::Context{tint:71,..Default::default()},raw:bridge::Raw{byte32:69,payload36:BASE+12,payload40:BASE,last_record:Some(0xdeadbeef),..Default::default()}};projection=[160,100];}check_record(&r,"before",&w.pool[0]);assert_eq!(hash(w.pool.iter().flatten().copied()),n("poolBefore")as u32);assert_eq!(hash(t.arena.iter().copied()),n("trailBefore")as u32);w.calls=0;w.requests=0;t.error=9;let camera=if s%3==0{[2000,2000]}else{[0,0]};let mut sound=s/8%2!=0;let(d,_)=step_part(&mut t,&mut w,&mut g,0,&mut projection,camera,&mut sound);check_record(&r,"after",&w.pool[0]);assert_eq!(hash(w.pool.iter().flatten().copied()),n("pool")as u32);assert_eq!(hash(t.arena.iter().copied()),n("trail")as u32);assert_eq!(w.calls,n("calls")as usize);assert_eq!(d,n("dispatch")as usize);assert_eq!(w.requests,n("emits")as usize);assert_eq!(sound,n("soundGate")!=0);assert_eq!(t.error,n("error")as u8);assert_eq!(projection,[n("projectX")as i16,n("projectY")as i16]);assert_eq!(g.raw.last_record,Some(n("last")as u32));assert_eq!(g.raw.payload36,n("payload")as u32);check_rng(&r,&w);}}
#[test]fn all_2304_original_playback_restore_callbacks_match_every_warm_pool(){
 use crate::original_building_fragments::Pool as Fragments;
 let source=if std::env::var_os("Z_NATIVE_TRACE_DIR").is_some(){fixture("v41-building-callers.jsonl")}else{vec![]};let mut tables=std::collections::BTreeMap::new();for r in source{if r["mode"]==0{tables.insert(r["kind"].as_i64().unwrap()as i8,r["templates"].as_array().unwrap().iter().map(|r|std::array::from_fn(|i|r[i].as_i64().unwrap()as i16)).collect::<Vec<[i16;6]>>());}}
 let rows=fixture("v43-trail-playback.jsonl");assert_eq!(rows.len(),2304);let mut prev=usize::MAX;let mut t=State::default();let mut builds=[[0u8;88];2];let mut pools=[Fragments::default(),Fragments::default()];let mut rng=seed(0,0,false);let mut crt=0usize;for r in rows{let n=|k:&str|r[k].as_i64().unwrap();let s=n("scenario")as usize;let kind=n("kind")as i8;let(h,stride)=header(kind).unwrap();let stride=usize::from(stride);if s!=prev{prev=s;t=State::default();crt=0;rng=seed(s,0,n("mp")!=0);for(i,b)in t.arena.iter_mut().enumerate(){*b=(s*13+i*7+19)as u8;}for f in 0..44{for part in 0..stride{let at=h+12+((f*stride+part)*10)as u32;t.put_word(at,400+part as i16*3+f as i16).unwrap();t.put_word(at+2,500+part as i16*5-f as i16).unwrap();t.put_word(at+4,[0,1,16,17,120,1782][(f+part)%6]).unwrap();t.write(at+6,&[(s*7+part*11+f*3)as u8,(f as i32-part as i32-16)as u8,f as u8]).unwrap();}}t.put_word(h,stride as i16).unwrap();for(o,v)in[(2,400),(4,500),(6,400),(8,500)]{t.put_word(h+o,v).unwrap();}t.write(h+10,&[n("frame")as u8+1,n("frame")as u8]).unwrap();for(slot,j)in t.jobs.iter_mut().enumerate(){for(i,b)in j.0.iter_mut().enumerate(){*b=(s*17+slot*11+i*7)as u8;}j.set_ptr(0,if slot<2{h}else{0});}for i in 0..2{let j=&mut t.jobs[i];j.set_ptr(4,0x1800000+i as u32*256);j.set(8,900+i as i16*500);j.set(10,700+i as i16*400);j.0[12]=n("frame")as u8;j.set_ptr(16,0);j.set(20,if i==0{0}else{n("delay")as i16});let b=&mut builds[i];for(j,v)in b.iter_mut().enumerate(){*v=(s*19+i*23+j*7)as u8;}raw_set(b,0,900+i as i16*500);raw_set(b,2,700+i as i16*400);b[4]=kind as u8;b[6]=234;raw_set(b,28,1000);raw_set(b,30,0);b[24..28].copy_from_slice(&(0x1801000u32+i as u32*900+90).to_le_bytes());b[32..36].copy_from_slice(&0x1802000u32.to_le_bytes());b[48..52].copy_from_slice(&h.to_le_bytes());b[64..68].copy_from_slice(&(0x1801000u32+i as u32*900).to_le_bytes());raw_set(b,80,if i==0{5}else{-1});for(slot,record)in pools[i].records.iter_mut().enumerate(){for(j,v)in record.bytes.iter_mut().enumerate(){*v=(s*23+i*31+slot*13+j*7)as u8;}record.set(0,-1);}}}
 let free=|t:&State|t.free_job().map_or(0,|i|JOB_BASE+i as u32*24);assert_eq!(free(&t),n("freeBefore")as u32);check_record(&r,"beforeJobs",&t.jobs[..2].iter().flat_map(|j|j.0).collect::<Vec<_>>());let camera=if s%5==0{[3000,3000]}else if s%3==0{[500,600]}else{[0,0]};let v=View{camera,size:[2048,2048],clip_min:[0,0],quality:n("quality")as i8,world_base:1138};let mut draws=vec![];let mut restore=0;for i in 0..64{let out=t.playback(i,v,(i<2).then(||[raw_word(&builds[i],0),raw_word(&builds[i],2)])).unwrap();for d in out.draws{draws.push(vec![i64::from(d.screen[0]),i64::from(d.screen[1]),i64::from(d.sprite),0,i64::from(d.angle),i64::from(d.height_global),i64::from(d.angle)]);}if let Some(job)=out.restore{restore+=1;let b=&mut builds[i];restore_raw(b,n("mp")!=0,||rng.next_u32(),||{let v=(s*3571+crt*131+0x1743)&32767;crt+=1;v as u16});pools[i].construct([raw_word(b,0),raw_word(b,2)],tables.get(&kind).map_or(&[][..],Vec::as_slice),raw_word(b,28)/5);pools[i].clear();restore_tail(b,0x1802000);t.complete(i,job.ptr(0)).unwrap();}}t.end_reader();if let Some(expected)=r.get("draws"){assert_eq!(draws,serde_json::from_value::<Vec<Vec<i64>>>(expected.clone()).unwrap());}else{assert_eq!(hash(draws.iter().flatten().flat_map(|v|v.to_le_bytes())),n("drawsHash")as u32);assert_eq!(draws.len(),n("drawsCount")as usize);}check_record(&r,"jobs",&t.jobs[..2].iter().flat_map(|j|j.0).collect::<Vec<_>>());assert_eq!(hash(t.jobs.iter().flat_map(|j|j.0)),n("allJobs")as u32);assert_eq!(hash(t.arena.iter().copied()),n("trail")as u32);for i in 0..2{check_record(&r,&format!("build{i}"),&builds[i]);}if !tables.is_empty(){assert_eq!(hash(pools.iter().flat_map(|p|p.records.iter().flat_map(|r|r.bytes))),n("fragments")as u32);}else{assert!(pools.iter().flat_map(|p|p.records.iter()).all(|r|r.word(0)==-1));}assert_eq!(restore,n("restore"));assert_eq!(crt,n("crt")as usize);assert_eq!(free(&t),n("freeAfter")as u32);assert_eq!(t.sound_clock,n("soundClock")as u32);assert_eq!(t.height_global,n("heightGlobal")as u32);assert_eq!(t.angle_global,n("angleGlobal")as u32);for i in 0..5{assert_eq!(rng.words[i],r[format!("r{i}")].as_u64().unwrap()as u32);}
 }
}

//Deterministic generated source record, matching the Java oracle's input.
fn particle_source(s:usize,r:&serde_json::Value)->[u8;44]{let mut b=std::array::from_fn(|j|(s*17+j*19)as u8);let mut set=|a:usize,n:i16|b[a..a+2].copy_from_slice(&n.to_le_bytes());for(a,n)in[(0,0),(2,0),(4,[-50,-1,0,1][s/3%4]),(6,if s%17==0{-200}else{346}),(8,420),(18,[-1,0,1,400][s/2%4]),(20,3),(26,[120,250,1138][s/5%3]),(28,250),(30,[0,7,-32,127][s/11%4])]{set(a,n);}b[10]=3;b[11]=(-2i8)as u8;b[12]=[-4i8,0,1,4][s/7%4]as u8;b[13]=4;b[14]=1;b[15]=37;b[16]=0;b[17]=0;b[22]=12;b[23]=(s&3)as u8;b[24]=11;b[25]=r["owner"].as_u64().unwrap()as u8;b[32]=r["stride"].as_u64().unwrap()as u8;b[33]=r["counter"].as_u64().unwrap()as u8;let h=BASE+r["header"].as_u64().unwrap()as u32*BLOCK as u32;let stride=b[32];b[36..40].copy_from_slice(&(h+12+u32::from(stride)*10*20).to_le_bytes());b[40..44].copy_from_slice(&h.to_le_bytes());b}
